sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToRecordProducer = function() { 
        var recordProducerSysId = 'ebf68edbc3472210319033fc05013162'; 
        var url = '/sp?id=record_producer&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-event {
    background: linear-gradient(135deg, #f3e5f5, #f9f1fc);
    border-radius: 20px;
    padding: 30px 20px;
    box-shadow: 0 8px 20px rgba(102, 51, 153, 0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.custom-action-card-event:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(102, 51, 153, 0.2);
}

.icon-wrapper-event {
    background: #6a1b9a;
    color: white;
    width: 80px;
    height: 80px;
    margin: 0 auto 20px auto;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    box-shadow: 0 4px 10px rgba(106, 27, 154, 0.4);
}

.custom-action-card-event h4 {
    margin-bottom: 20px;
    font-weight: bold;
    color: #6a1b9a;
}

.action-btn-event {
    background: #8e24aa;
    color: white;
    padding: 12px 20px;
    font-size: 16px;
    border: none;
    border-radius: 10px;
    width: 100%;
    transition: background 0.3s ease;
}

.action-btn-event:hover {
    background: #6a1b9a;
    color: #fff;
}
